1	import { Component, computed, inject, signal } from '@angular/core';
2	import { takeUntilDestroyed, toObservable } from '@angular/core/rxjs-interop';
3	import { EMPTY, catchError, switchMap } from 'rxjs';
4	import { VeranstaltungenService } from '../shared/api/veranstaltungen.service';
5	import { Veranstaltung } from '../shared/models/veranstaltung';
6	import { EventCard } from '../shared/ui/event-card/event-card';
7	import { FilterBar } from '../shared/ui/filter-bar/filter-bar';
8	
9	type Ladezustand = 'laedt' | 'geladen' | 'fehler';
10	
11	@Component({
12	  selector: 'app-programmuebersicht',
13	  imports: [EventCard, FilterBar],
14	  templateUrl: './programmuebersicht.html',
15	  styleUrl: './programmuebersicht.scss'
16	})
17	export class Programmuebersicht {
18	  private readonly veranstaltungenService = inject(VeranstaltungenService);
19	
20	  readonly von = signal<string | null>(null);
21	  readonly bis = signal<string | null>(null);
22	  readonly spielstaetteId = signal<string | null>(null);
23	
24	  readonly ladezustand = signal<Ladezustand>('laedt');
25	  readonly veranstaltungen = signal<Veranstaltung[]>([]);
26	  readonly spielstaetten = signal<{ id: string; name: string }[]>([]);
27	
28	  protected readonly skeletonPlatzhalter = [0, 1, 2, 3];
29	
30	  protected readonly filterAktiv = computed(
31	    () => this.von() !== null || this.bis() !== null || this.spielstaetteId() !== null
32	  );
33	
34	  private readonly filter = computed(() => ({
35	    von: this.von(),
36	    bis: this.bis(),
37	    spielstaetteId: this.spielstaetteId()
38	  }));
39	
40	  protected filterZuruecksetzen(): void {
41	    this.von.set(null);
42	    this.bis.set(null);
43	    this.spielstaetteId.set(null);
44	  }
45	
46	  constructor() {
47	    toObservable(this.filter)
48	      .pipe(
49	        switchMap((filter) => {
50	          this.ladezustand.set('laedt');
51	          return this.veranstaltungenService
52	            .getVeranstaltungen(filter.von, filter.bis, filter.spielstaetteId)
53	            .pipe(
54	              catchError(() => {
55	                this.ladezustand.set('fehler');
56	                return EMPTY;
57	              })
58	            );
59	        }),
60	        takeUntilDestroyed()
61	      )
62	      .subscribe((veranstaltungen) => {
63	        this.veranstaltungen.set(veranstaltungen);
64	        this.ladezustand.set('geladen');
65	      });
66	
67	    this.veranstaltungenService
68	      .getVeranstaltungen()
69	      .pipe(
70	        catchError(() => EMPTY),
71	        takeUntilDestroyed()
72	      )
73	      .subscribe((veranstaltungen) => {
74	        const eindeutigeSpielstaetten = new Map<string, string>();
75	        for (const veranstaltung of veranstaltungen) {
76	          eindeutigeSpielstaetten.set(veranstaltung.spielstaetteId, veranstaltung.spielstaetteName);
77	        }
78	        this.spielstaetten.set(
79	          [...eindeutigeSpielstaetten.entries()]
80	            .map(([id, name]) => ({ id, name }))
81	            .sort((a, b) => a.name.localeCompare(b.name, 'de'))
82	        );
83	      });
84	  }
85	}
