  });

  it('setzt bei Klick auf "Filter zurücksetzen" im gefilterten Leerzustand beide Filter zurück', () => {
    const getVeranstaltungen = vi.fn().mockReturnValue(of([]));
    const fixture = createFixture({ getVeranstaltungen });
